10	/// [insta.rs](https://insta.rs/docs) snapshot testing
11	///
12	/// For better development workflow, run
13	/// `cargo watch -i '*.new' -x 'test -p biome_js_formatter formatter'`
14	///
15	/// To review and commit the snapshots, `cargo install cargo-insta`, and run
16	/// `cargo insta review` or `cargo insta accept`
17	///
18	/// The input and the expected output are stored as dedicated files in the `tests/specs` directory where
19	/// the input file name is `{spec_name}.json` and the output file name is `{spec_name}.json.snap`.
20	///
21	/// Specs can be grouped in directories by specifying the directory name in the spec name. Examples:
22	///
23	/// # Examples
24	///
25	/// * `json/null` -> input: `tests/specs/json/null.json`, expected output: `tests/specs/json/null.json.snap`
26	/// * `null` -> input: `tests/specs/null.json`, expected output: `tests/specs/null.json.snap`
27	pub fn run(spec_input_file: &str, _expected_file: &str, test_directory: &str, file_type: &str) {
28	    let root_path = Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/specs/"));
29	
30	    let Some(test_file) = SpecTestFile::try_from_file(spec_input_file, root_path) else {
31	        return;
32	    };
33	
34	    let mut source_type: JsFileSource = test_file.input_file().as_path().try_into().unwrap();
35	    if file_type != "module" {
36	        source_type = source_type.with_module_kind(ModuleKind::Script);
37	    }
38	
39	    let options = JsFormatOptions::new(source_type);
40	    let language = language::JsTestFormatLanguage::new(source_type);
41	
42	    let snapshot = SpecSnapshot::new(test_file, test_directory, language, options);
43	
44	    snapshot.test()
45	}
