84	                } else {
85	                    write!(f, [indent(&consequent)])
86	                }
87	            });
88	            if is_consequent_nested {
89	                // Add parentheses around the consequent if it is a conditional expression and fits on the same line
90	                // so that it's easier to identify the parts that belong to a conditional expression.
91	                // `a ? b ? c: d : e` -> `a ? (b ? c: d) : e
92	                write!(
93	                    f,
94	                    [
95	                        if_group_fits_on_line(&text("(")),
96	                        consequent,
97	                        if_group_fits_on_line(&text(")"))
98	                    ]
