29	impl Iterator for AllFiles {
30	    type Item = Result<PathBuf, &'static str>;
31	
32	    fn next(&mut self) -> Option<Self::Item> {
33	        loop {
34	            match self.0.next() {
35	                Some(Ok(entry)) => {
36	                    let file_name = match entry.file_name().to_str().ok_or("File name not UTF8") {
37	                        Ok(v) => v,
38	                        Err(e) => return Some(Err(e)),
39	                    };
40	
41	                    if file_name.contains("expected") {
42	                        continue;
43	                    }
44	                    let meta = match entry.metadata().map_err(|_| "Cannot open file") {
45	                        Ok(v) => v,
46	                        Err(e) => return Some(Err(e)),
47	                    };
48	                    if meta.is_file() {
49	                        let path = entry.path().to_path_buf();
50	                        break Some(Ok(path));
51	                    }
52	                }
53	                _ => break None,
54	            }
55	        }
56	    }
57	}
