59	fn transform_file_name(input: &str) -> String {
60	    let mut result = String::new();
61	    for char in input.chars() {
62	        match char {
63	            '-' | '.' | '@' | '+' => {
64	                result.push('_');
65	            }
66	            char if char.is_uppercase() => {
67	                result.push('_');
68	                result.extend(char.to_lowercase());
69	            }
70	            char => {
71	                result.push(char);
72	            }
73	        }
74	    }
75	
76	    let is_keyword = matches!(
77	        result.as_str(),
78	        "await"
79	            | "break"
80	            | "try"
81	            | "do"
82	            | "for"
83	            | "return"
84	            | "if"
85	            | "while"
86	            | "in"
87	            | "async"
88	            | "else"
89	            | "as"
90	            | "abstract"
91	            | "enum"
92	            | "static"
93	            | "yield"
94	            | "type"
95	            | "super"
96	            | "typeof"
97	            | "const"
98	    );
99	
100	    let is_number = result
101	        .chars()
102	        .next()
103	        .unwrap()
104	        .to_string()
105	        .parse::<u32>()
106	        .is_ok();
107	
108	    if is_keyword {
109	        result.push('_');
110	    } else if is_number {
111	        result = "_".to_string() + &result;
112	    }
113	
114	    result
115	}
