118	struct Modules {
119	    modules: HashMap<String, Modules>,
120	    tests: Vec<proc_macro2::TokenStream>,
121	}
122	
123	impl Modules {
124	    fn insert<'a>(
125	        &mut self,
126	        mut path: impl Iterator<Item = &'a str>,
127	        test: proc_macro2::TokenStream,
128	    ) {
129	        match path.next() {
130	            Some(module) => {
131	                let name = transform_file_name(module);
132	                self.modules.entry(name).or_default().insert(path, test);
133	            }
134	            None => {
135	                self.tests.push(test);
136	            }
137	        }
138	    }
139	
140	    fn print(self, output: &mut proc_macro2::TokenStream) {
141	        for (name, module) in self.modules {
142	            let name = syn::Ident::new(&name, Span::call_site());
143	
144	            let mut stream = proc_macro2::TokenStream::new();
145	            module.print(&mut stream);
146	            output.extend(quote! {
147	                mod #name { #stream }
148	            });
149	        }
150	
151	        output.extend(self.tests);
152	    }
153	}
